  /**
   * Get payment history for a user
   * 
   * @route GET /api/admin/user-subscriptions/:userId/payment-history
   * @access Admin
   * @param {AuthenticatedRequest} req - Express request object with user ID
   * @param {Response} res - Express response object
   * @returns {Promise<Response>} Returns payment history for the user
   * 
   * @throws {401} Unauthorized if user is not authenticated
   * @throws {403} Forbidden if user is not an admin
   */
  async getUserPaymentHistory(req, res) {
    try {
      const { userId } = req.params;
      const { db: db2 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const { payments: payments2, subscriptionPlans: subscriptionPlans2 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
      const { eq: eq58, desc: desc30 } = await import("drizzle-orm");
      const paymentHistoryData = await db2.select({
        id: payments2.id,
        userId: payments2.userId,
        planId: payments2.planId,
        planName: subscriptionPlans2.name,
        paymentType: payments2.paymentType,
        amount: payments2.amount,
        currency: payments2.currency,
        orderId: payments2.orderId,
        paymentReference: payments2.paymentReference,
        paymentGateway: payments2.paymentGateway,
        paidAt: payments2.paidAt
      }).from(payments2).leftJoin(subscriptionPlans2, eq58(payments2.planId, subscriptionPlans2.id)).where(eq58(payments2.userId, userId)).orderBy(desc30(payments2.paidAt));
      const paymentTypeLabels = {
        "new_subscription": "Initial Purchase",
        "upgrade": "Upgrade",
        "renewal": "Renewal"
      };
      const paymentHistory = paymentHistoryData.map((payment) => ({
        ...payment,
        planId: payment.planId || "",
        planName: payment.planName || "Unknown Plan",
        paymentType: payment.paymentType ? paymentTypeLabels[payment.paymentType] || "Payment" : "Payment"
      }));
      return this.sendSuccess(res, paymentHistory);
    } catch (error) {
      return this.handleError(res, error, "AdminController.getUserPaymentHistory");
    }
  }
