import rateLimit2 from "express-rate-limit";
var versionCreationLimiter = rateLimit2({
  windowMs: 15 * 60 * 1e3,
  // 15 minutes
  max: 5,
  // 5 version creations per 15 minutes per admin
  message: "Too many version creation requests. Please try again in 15 minutes.",
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.user?.id || "unauthenticated",
  skip: (req) => !req.user
  // Skip if somehow no user (requireAdmin should prevent this)
});
var migrationLimiter = rateLimit2({
  windowMs: 60 * 60 * 1e3,
  // 1 hour
  max: 3,
  // 3 migrations per hour per admin
  message: "Too many migration requests. Please try again in 1 hour.",
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.user?.id || "unauthenticated",
  skip: (req) => !req.user
});
var bulkNotificationLimiter = rateLimit2({
  windowMs: 30 * 60 * 1e3,
  // 30 minutes
  max: 1,
  // 1 bulk notification per 30 minutes per admin
  message: "Too many bulk notification requests. Please try again in 30 minutes.",
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.user?.id || "unauthenticated",
  skip: (req) => !req.user
});
var bulkOperationsLimiter = rateLimit2({
  windowMs: 15 * 60 * 1e3,
  // 15 minutes
  max: 5,
  // 5 bulk operations per 15 minutes per admin
  message: "Too many bulk operation requests. Please try again in 15 minutes.",
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.user?.id || "unauthenticated",
  skip: (req) => !req.user
});
