// server/middleware/webhook-security.ts
init_logger();
init_config();
import rateLimit3 from "express-rate-limit";
var webhookRateLimit = rateLimit3({
  windowMs: 1 * 60 * 1e3,
  // 1 minute
  max: 10,
  // 10 requests per minute per IP
  message: "Too many webhook requests",
  standardHeaders: true,
  // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
  // Disable `X-RateLimit-*` headers
  // Note: Using default keyGenerator which handles IPv6 correctly via req.ip
  // Express's trust proxy setting ensures req.ip reflects the true client IP
  // Custom handler for rate limit exceeded
  handler: (req, res) => {
    const clientIp = req.ip || "unknown";
    logger_default.warn("Webhook rate limit exceeded", {
      clientIp,
      path: req.path,
      method: req.method
    });
    res.status(429).json({
      success: false,
      error: "Too Many Requests",
      message: "Too many webhook requests"
    });
  }
});

