// server/middleware/partner-auth.middleware.ts
init_logger();
var requirePartner = (req, res, next) => {
  const authReq = req;
  const user = authReq.user;
  if (!user) {
    logger_default.warn("Unauthorized access attempt: no user found in request");
    return next(createHttpError.unauthorized("Authentication required"));
  }
  if (user.userType !== "partner") {
    logger_default.warn("Unauthorized access attempt: user is not a partner", {
      userId: user.id,
      userType: user.userType
    });
    return next(createHttpError.forbidden("Access restricted to partners only"));
  }
  next();
};

